head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > E > onbeforetabclose]<br/>Tab 페이지가 제거되기 직전에 발생하며 반환값으로 취소할 수 있습니다.",
    "validation" : [
        "반환값으로 미설정 또는 true 설정 시 Tab 페이지를 제거한 후 ontabclose 이벤트를 발생시킵니다.",
        "false 설정 시 Tab 페이지의 제거를 취소합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        closable : true,
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbeforetabclose", "ontabclose"]);

    $c.gcm.createBasicTabControl(cList, eList);    
}



scwin.target1_onbeforetabclose = function (tabId, index) {
    let returnValue = par_return.getText();

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforetabclose=====");
    wf_body_bottom.getObj("scwin").setReturnValue("tabId : " + tabId);
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + index);

    if (returnValue == "true")
        return true;
    else if (returnValue == "false")
        return false;
    else
        return;
}



scwin.target1_ontabclose = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontabclose=====");
}
